const solicitud = $input.first().json;

const {
  request_id,
  cliente,
  profesional,
  fecha,
  hora,
  duracion_minutos,
  aceptacion_explicita
} = solicitud;

// Normalización de datos
const datos = {
  request_id: String(request_id ?? '').trim(),
  cliente: String(cliente ?? '').trim(),
  profesional: String(profesional ?? '').trim(),
  fecha: String(fecha ?? '').trim(),
  hora: String(hora ?? '').trim(),
  duracion_minutos: Number(duracion_minutos),
  aceptacion_explicita: aceptacion_explicita === true
};

// Validaciones
const errores = [];

if (!datos.request_id) {
  errores.push('request_id obligatorio');
}

if (!datos.cliente) {
  errores.push('cliente obligatorio');
}

// Si no se especifica profesional,
// se interpreta como "sin preferencia".
if (!datos.profesional) {
  datos.profesional = 'SIN_PREFERENCIA';
}

// Catálogo de profesionales habilitados
const profesionalesValidos = [
  'Martin',
  'Lucas',
  'Nicolas',
  'SIN_PREFERENCIA'
];

// Validar que el profesional pertenezca al catálogo
if (!profesionalesValidos.includes(datos.profesional)) {
  errores.push('Profesional no reconocido');
}

if (!/^\d{4}-\d{2}-\d{2}$/.test(datos.fecha)) {
  errores.push('fecha inválida');
} else {
  const [y, m, d] = datos.fecha.split('-').map(Number);
  const fechaUTC = new Date(Date.UTC(y, m - 1, d));

  if (
    fechaUTC.getUTCFullYear() !== y ||
    fechaUTC.getUTCMonth() !== m - 1 ||
    fechaUTC.getUTCDate() !== d
  ) {
    errores.push('fecha inexistente');
  }
}

if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(datos.hora)) {
  errores.push('hora inválida');
}

if (
  !Number.isInteger(datos.duracion_minutos) ||
  datos.duracion_minutos <= 0
) {
  errores.push('duracion_minutos inválida');
}

if (!datos.aceptacion_explicita) {
  errores.push('No existe aceptación explícita del cliente');
}

// Resultado del contrato
const contrato_valido = errores.length === 0;

return [{
  json: {
    ...datos,
    contrato_valido,
    estado: contrato_valido
      ? 'validado'
      : 'rechazado',
    errores
  }
}];

const solicitud = $('Code in JavaScript').first().json;
const eventos = $input.all();

const profesionales = ['Martin', 'Lucas', 'Nicolas'];

const normalizar = (valor) =>
  String(valor ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

const solicitado = normalizar(solicitud.profesional);
const sinPreferencia = solicitado === 'sin_preferencia';
const duracion = Number(solicitud.duracion_minutos);

const inicio = DateTime.fromISO(
  `${solicitud.fecha}T${solicitud.hora}`,
  { zone: 'America/Argentina/Buenos_Aires' }
);

if (!inicio.isValid) {
  throw new Error('Fecha u hora inválida');
}

if (!Number.isInteger(duracion) || duracion <= 0) {
  throw new Error('Duración inválida');
}

if (!sinPreferencia &&
    !profesionales.some(p => normalizar(p) === solicitado)) {
  throw new Error('Profesional no reconocido');
}

const fin = inicio.plus({ minutes: duracion });
const ocupados = new Set();
const conflictos = [];

for (const item of eventos) {
  const evento = item.json;

  if (!evento.id || evento.status === 'cancelled') continue;

  const desdeISO = evento.start?.dateTime;
  const hastaISO = evento.end?.dateTime;

  if (!desdeISO || !hastaISO) {
    throw new Error(`Evento sin horario válido: ${evento.id}`);
  }

  const desde = DateTime.fromISO(desdeISO);
  const hasta = DateTime.fromISO(hastaISO);

  if (!desde.isValid || !hasta.isValid) {
    throw new Error(`Fechas inválidas en evento: ${evento.id}`);
  }

  if (desde < fin && hasta > inicio) {
    const partes = String(evento.summary ?? '').split(' - ');
    const profesionalEvento = normalizar(partes.at(-1))
      .split(',')[0]
      .trim();

    const reconocido = profesionales.some(
      p => normalizar(p) === profesionalEvento
    );

    if (!reconocido) {
      throw new Error(
        `Evento sin profesional reconocido: ${evento.id}`
      );
    }

    ocupados.add(profesionalEvento);

    if (sinPreferencia || profesionalEvento === solicitado) {
      conflictos.push({
        id: evento.id,
        titulo: evento.summary,
        inicio: desdeISO,
        fin: hastaISO
      });
    }
  }
}

const candidatos = sinPreferencia
  ? profesionales
  : profesionales.filter(p => normalizar(p) === solicitado);

const disponibles = candidatos.filter(
  p => !ocupados.has(normalizar(p))
);

const asignado = disponibles[0] ?? null;
const disponible = asignado !== null;

return [{
  json: {
    ...solicitud,
    profesional: asignado,
    profesional_solicitado: solicitud.profesional,
    profesionales_disponibles: disponibles,
    duracion_minutos: duracion,
    disponible,
    conflictos,
    estado: disponible ? 'disponible' : 'no_disponible'
  }
}];

const evento = $input.first().json;

const solicitud = $('Code | Validar conflictos')
  .first().json;

if (!evento.id || evento.status === 'cancelled') {
  throw new Error(
    'Google Calendar no confirmó la creación del evento'
  );
}

return [{
  json: {
    request_id: solicitud.request_id,
    cliente: solicitud.cliente,
    profesional: solicitud.profesional,
    profesional_solicitado: solicitud.profesional_solicitado,
    fecha: solicitud.fecha,
    hora: solicitud.hora,
    duracion_minutos: solicitud.duracion_minutos,
    disponible: true,
    estado: 'confirmada',
    evento_creado: true,
    event_id: evento.id,
    reserva_confirmada: true,
    conflictos: []
  }
}];
